CREATE OR REPLACE FUNCTION calculate_risk_zone() RETURNS TRIGGER AS $$
DECLARE
    ted_minutes NUMERIC;
    transit_hours NUMERIC;
    transit_minutes NUMERIC;
    tirp_percent NUMERIC;
    risk_zone TEXT;
    exc_count INT;
    exc_dur INT;
BEGIN
    -- Get TED from env_metrics (temperature.excursion_duration_min)
    ted_minutes := COALESCE((NEW.env_metrics->'temperature'->>'excursion_duration_min')::NUMERIC, 0);

    -- Get excursion count
    exc_count := COALESCE((NEW.env_metrics->'temperature'->>'excursion_count')::INT, 0);
    exc_dur := COALESCE((NEW.env_metrics->'temperature'->>'excursion_duration_min')::INT, 0);

    -- Get transit time from linked shipment
    SELECT (s.shipment_overview->'timing_performance'->>'actual_duration_hrs')::NUMERIC
    INTO transit_hours
    FROM shipments s
    WHERE s.reckey = NEW.reckeylink;

    -- Calculate TIRP
    IF transit_hours IS NOT NULL AND transit_hours > 0 THEN
        transit_minutes := transit_hours * 60;
        IF transit_minutes > ted_minutes THEN
            tirp_percent := ((transit_minutes - ted_minutes) / transit_minutes) * 100;
        ELSE
            tirp_percent := 0;
        END IF;

        -- Classify risk zone
        -- Red Zone: TIRP < 95% or any excursion > 60 min
        -- Yellow Zone: 95% <= TIRP <= 98% or any excursion 30-60 min
        -- Green Zone: TIRP > 98% and no excursions > 30 min

        IF tirp_percent < 95 OR exc_dur > 60 THEN
            risk_zone := 'Red Zone';
        ELSIF (tirp_percent >= 95 AND tirp_percent <= 98) OR (exc_dur >= 30 AND exc_dur <= 60) THEN
            risk_zone := 'Yellow Zone';
        ELSE
            risk_zone := 'Green Zone';
        END IF;
    ELSE
        tirp_percent := NULL;
        risk_zone := 'Unknown';
    END IF;

    -- Add calculated zone and percent back into the JSON field
    NEW.env_metrics := jsonb_set(NEW.env_metrics, '{risk_assessment}', 
        jsonb_build_object('tirp_percent', ROUND(CAST(tirp_percent AS numeric), 2), 'risk_zone', risk_zone));

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

