CREATE OR REPLACE FUNCTION calculate_risk_zone() RETURNS TRIGGER AS $$
DECLARE
    ted_minutes NUMERIC;
    transit_hours NUMERIC;
    tirp_percent NUMERIC;
    risk_zone TEXT;
    exc_dur INT;
BEGIN
    ted_minutes := COALESCE((NEW.env_metrics->'temperature'->>'excursion_duration_min')::NUMERIC, 0);
    exc_dur := COALESCE((NEW.env_metrics->'temperature'->>'excursion_duration_min')::INT, 0);

    SELECT CAST(s.shipment_overview->'timing_performance'->>'actual_duration_hrs' AS NUMERIC) INTO transit_hours
    FROM shipments s WHERE s.reckey = NEW.reckeylink LIMIT 1;

    IF transit_hours IS NOT NULL AND transit_hours > 0 THEN
        IF (transit_hours * 60) > ted_minutes THEN
            tirp_percent := ROUND(CAST(((transit_hours * 60 - ted_minutes) / (transit_hours * 60)) * 100 AS numeric), 2);
        ELSE
            tirp_percent := 0;
        END IF;

        IF tirp_percent < 95 OR exc_dur > 60 THEN
            risk_zone := 'Red Zone';
        ELSIF (tirp_percent >= 95 AND tirp_percent <= 98) OR (exc_dur >= 30 AND exc_dur <= 60) THEN
            risk_zone := 'Yellow Zone';
        ELSE
            risk_zone := 'Green Zone';
        END IF;
    ELSE
        tirp_percent := 0;
        risk_zone := 'Unknown';
    END IF;

    NEW.env_metrics := jsonb_set(NEW.env_metrics, '{risk_zone}', to_jsonb(risk_zone));
    NEW.env_metrics := jsonb_set(NEW.env_metrics, '{tirp_percent}', to_jsonb(tirp_percent));

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

